// PlaceTags — the word-tags a public venue earns instead of a
// headcount (Round 28; sim §§28–30). Rendered on venue cards; the
// derivation lives in utils/placeTags.ts (deterministic, slow and
// sticky by construction — the same venue shows the same tags all
// day). Earned tags cannot be bought. The one paid tag,
// Recognized (the Round 29 tier, sim §13), renders as a FILLED
// gold chip that says "Paid partner" out loud — it never wears
// the earned tags' outlined look, so money is never disguised as
// an earned signal.

import React from 'react';
import { Box, Chip } from '@mui/material';
import type { DemoVenue } from '../data/venues';
import type { VenueBuzz } from '../data/venueBuzz';
import { placeTagsFor, type PlaceTag } from '../utils/placeTags';

const FAMILY_EMOJI: Record<PlaceTag['family'], string> = {
  crowd: '🔥',
  identity: '📍',
  offer: '🎁',
};

// The paid badge (sim §13): filled, gold, and labelled as paid in
// plain words. Shared by the venue cards, the selected-venue
// panel (via PlaceTags) and the Worth the Trip feed.
export function RecognizedChip() {
  return (
    <Chip
      label="⭐ Recognized · Paid partner"
      size="small"
      color="warning"
      data-tag="Recognized"
      data-tag-family="offer"
      data-paid="true"
    />
  );
}

export default function PlaceTags({ venue, buzz }: { venue: DemoVenue; buzz?: VenueBuzz }) {
  const tags = placeTagsFor(venue, buzz);
  if (tags.length === 0) return null;
  return (
    <Box
      data-testid="place-tags"
      data-venue-id={venue.id}
      sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', mt: 0.75 }}
    >
      {tags.map(tag =>
        tag.label === 'Recognized' ? (
          <RecognizedChip key={tag.label} />
        ) : (
          <Chip
            key={tag.label}
            label={`${FAMILY_EMOJI[tag.family]} ${tag.label}`}
            size="small"
            variant="outlined"
            data-tag={tag.label}
            data-tag-family={tag.family}
          />
        )
      )}
    </Box>
  );
}
