// The app's own live URL, used as the redirect target for Supabase
// auth emails (sign-up confirmation, password reset). The app is
// served from GitHub Pages under the /GLACER basename, so the
// redirect must be derived from the current origin + that basename
// — a bare origin would land the email link outside the app, and
// the Supabase project's default site URL is a stale dev address.
// One helper so every auth email points at the same place.
export const appUrl = (): string =>
  `${window.location.origin}${process.env.REACT_APP_BASENAME || '/GLACER'}/`;
