import { DEMO_VENUES } from '../data/venues';
import { getNavitarModel } from './navitarArt';

// The showcase-model resolution chain, shared by Stroll and the AR
// View page (run 2 add-on fix). A navitar record's OWN modelUrl is
// only one carrier of its model: the demo-opponent twin (same name +
// element in the business pool), a venue person's fighter, and the
// NAVITAR_MODELS registry all carry models for records that have
// none of their own — adopted heroes are the common case. Stroll ran
// this chain from the start; the AR View page passed the record's
// modelUrl directly and skipped it, so the same navitar could stroll
// in 3D yet stand in AR as a flat card. One chain, both surfaces.
export interface ResolvedShowcaseModel {
  modelUrl: string;
  modelZoom?: number;
}

interface ModelCarrier {
  name: string;
  element: string;
  modelUrl?: string;
  modelZoom?: number;
}

export function resolveShowcaseModel(
  record: ModelCarrier,
  businessNavitars: ModelCarrier[]
): ResolvedShowcaseModel | null {
  if (record.modelUrl) return { modelUrl: record.modelUrl, modelZoom: record.modelZoom };
  const demo = businessNavitars.find(
    n => n.name === record.name && n.element === record.element && n.modelUrl
  );
  if (demo?.modelUrl) return { modelUrl: demo.modelUrl, modelZoom: demo.modelZoom };
  for (const venue of DEMO_VENUES) {
    const person = venue.people.find(
      p => p.navitarName === record.name && p.navitarElement === record.element && p.navitarModelUrl
    );
    if (person?.navitarModelUrl)
      return { modelUrl: person.navitarModelUrl, modelZoom: person.navitarModelZoom };
  }
  const reg = getNavitarModel(record.name, record.element);
  return reg ? { modelUrl: reg.modelUrl, modelZoom: reg.modelZoom } : null;
}
