// Incoming friend-request producer (Round 26, Eddie 2026-11-18)
// — the add-by-username door's other side. Headless, like the
// other producers: it seeds the demo's incoming friend requests
// into the social store and announces each one through the
// notifications store; it renders nothing.
//
// Shape (the brief's discipline, mirroring the Round 22 message
// producer's trigger discipline):
// - Seeding happens ONCE per device (the store's incomingSeeded
//   flag): up to two demo people — never a friend, never a blocked
//   person, nobody with an outgoing request on file — have "sent"
//   the player a request (utils/social.seedIncomingRequests).
// - The announcement is TYPE-ONLY, by Eddie's law: the record's
//   title is the type plus the sender ("🤝 Friend request from
//   @theo") and its body is a generic pointer to Friends. A friend
//   request carries no message text, so nothing beyond type +
//   sender exists to ride in the record or the toast.
// - The record id is stable per person and the store dedupes by
//   id, so re-firing can never duplicate or re-toast a request.
//   A request the player already answered is never announced.
// - It waits for a quiet moment: the player is not standing on
//   /friends (they'd see the section itself) and no other toast
//   is up — news doesn't pile on news. One announcement per poll
//   tick, so two seeded requests arrive as two separate toasts.
import React, { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useNotifications } from '../contexts/NotificationsContext';
import { loadNotifications } from '../utils/notifications';
import {
  demoHandle,
  demoPersonById,
  loadSocial,
  saveSocial,
  seedIncomingRequests,
} from '../utils/social';

const FIRST_CHECK_MS = 5000;
const POLL_MS = 4000;
const GIVE_UP_MS = 150000;

export function incomingRequestNotificationId(personId: string): string {
  return `friend-request-incoming-${personId}`;
}

const IncomingRequestProducer: React.FC = () => {
  const { notify, toasts } = useNotifications();
  const location = useLocation();
  const toastsRef = useRef(toasts);
  toastsRef.current = toasts;
  const pathRef = useRef(location.pathname);
  pathRef.current = location.pathname;

  useEffect(() => {
    // Seed synchronously on first mount, so the Incoming section
    // exists on Friends even if the player goes straight there —
    // only the ANNOUNCEMENT waits for a quiet moment.
    const { state, seededIds } = seedIncomingRequests(loadSocial());
    if (seededIds.length > 0) saveSocial(state);

    let stopped = false;
    let poll: number | null = null;
    const startedAt = Date.now();

    const attempt = () => {
      if (stopped) return;
      if (Date.now() - startedAt > GIVE_UP_MS) return;
      const social = loadSocial();
      const stored = new Set(loadNotifications().map(r => r.id));
      const owed = Object.entries(social.incoming)
        .filter(
          ([personId, status]) =>
            status === 'pending' &&
            !social.blocked.includes(personId) &&
            !stored.has(incomingRequestNotificationId(personId))
        )
        .map(([personId]) => personId);
      if (owed.length === 0) {
        stopped = true;
        if (poll !== null) window.clearInterval(poll);
        return;
      }
      // Not while the player is standing on Friends, and not on
      // top of another pop-up.
      if (pathRef.current.startsWith('/friends')) return;
      if (toastsRef.current.length > 0) return;

      const entry = demoPersonById(owed[0]);
      if (!entry) return;
      notify({
        id: incomingRequestNotificationId(entry.person.id),
        kind: 'friend',
        title: `🤝 Friend request from ${demoHandle(entry.person)}`,
        body: 'Tap to open Friends and answer it',
        route: '/friends',
        personId: entry.person.id,
        demo: true,
      });
    };

    const first = window.setTimeout(() => {
      attempt();
      poll = window.setInterval(attempt, POLL_MS);
    }, FIRST_CHECK_MS);
    return () => {
      stopped = true;
      window.clearTimeout(first);
      if (poll !== null) window.clearInterval(poll);
    };
  }, [notify]);

  return null;
};

export default IncomingRequestProducer;
