// GLACER Wallet (Round 20, Eddie 2026-11-17) — one screen, one
// ledger (utils/wallet.ts), five sections: Points, Deposited $,
// Earnings $, Your Share $, Ownership. Design of record:
// goals/glacer-ecosystem-assembly/files/glacer-wallet-design-v1.md
// (v1 + v2/v3/v4 addenda).
//
// The house model, in Eddie's words, is the page's headline
// because customers are to be TOLD it: revenue goes back to the
// user, being a user carries ownership, the share back is
// "thanks for helping us grow," and money is worth more kept
// in-system than cashed out — "that way we loop the money."
//
// HONEST SCOPE: no payment rail is connected (Stripe Connect is
// the design rail; connecting it needs Eddie's separate
// approval), so this wallet is DEMO-framed with fictional
// on-device balances, labeled DEMO the way the app labels every
// demo surface. Deposits and cash-outs are NOT executable —
// their buttons explain exactly that and change no state, the
// Round 19 Buy-dialog pattern. The converter DOES work, locally:
// Points -> Real Bucks at the settled rate (100 Points = 1 Real
// Buck; $1.25 in-system vs $1.00 cashed out), one-way, recorded
// in the ledger like every other movement.
//
// Eddie's still-open calls (cut % on player sales, Share-pool %,
// card-fee handling) appear NOWHERE as numbers in this UI — the
// Share section says plainly the rate is his to set.
import React, { useState } from 'react';
import {
  Box,
  Button,
  Chip,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import {
  POINTS_PER_REAL_BUCK,
  REAL_BUCK_CASH_OUT_CENTS,
  REAL_BUCK_IN_SYSTEM_CENTS,
  convertPointsToRealBucks,
  deriveBalances,
  formatUSD,
  loadWallet,
  saveWallet,
  type WalletEntry,
  type WalletState,
} from '../utils/wallet';

function entryDeltaSummary(e: WalletEntry): string {
  const parts: string[] = [];
  if (e.pointsDelta) parts.push(`${e.pointsDelta > 0 ? '+' : ''}${e.pointsDelta} Points`);
  if (e.depositedDelta)
    parts.push(
      `${e.depositedDelta > 0 ? '+' : '−'}${formatUSD(Math.abs(e.depositedDelta))} Deposited`
    );
  if (e.earningsDelta)
    parts.push(
      `${e.earningsDelta > 0 ? '+' : '−'}${formatUSD(Math.abs(e.earningsDelta))} Earnings`
    );
  if (e.shareDelta)
    parts.push(`${e.shareDelta > 0 ? '+' : '−'}${formatUSD(Math.abs(e.shareDelta))} Your Share`);
  if (e.realBucksDelta)
    parts.push(
      `${e.realBucksDelta > 0 ? '+' : ''}${e.realBucksDelta} Real Buck${Math.abs(e.realBucksDelta) === 1 ? '' : 's'}`
    );
  return parts.join(' · ');
}

const Section: React.FC<{
  title: string;
  testId: string;
  balanceTestId: string;
  balance: string;
  children: React.ReactNode;
}> = ({ title, testId, balanceTestId, balance, children }) => (
  <Paper sx={{ p: 3, mb: 3 }} data-testid={testId}>
    <Box
      sx={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'baseline',
        gap: 2,
        flexWrap: 'wrap',
      }}
    >
      <Typography variant="h6">{title}</Typography>
      <Typography variant="h5" data-testid={balanceTestId} sx={{ fontWeight: 800 }}>
        {balance}
      </Typography>
    </Box>
    {children}
  </Paper>
);

const Wallet: React.FC = () => {
  const [wallet, setWallet] = useState<WalletState>(() => loadWallet());
  const balances = deriveBalances(wallet);
  const [convertInput, setConvertInput] = useState('1');
  const [convertError, setConvertError] = useState<string | null>(null);
  const [convertNote, setConvertNote] = useState<string | null>(null);
  // 'deposit' | 'cashout' — both doors are closed until the rail
  // connects; one dialog explains either, changing no state.
  const [closedDoor, setClosedDoor] = useState<'deposit' | 'cashout' | null>(null);

  const handleConvert = () => {
    const bucks = Number(convertInput);
    if (!convertInput.trim() || !Number.isInteger(bucks) || bucks < 1) {
      setConvertError('Enter a whole number of Real Bucks — 1 or more.');
      setConvertNote(null);
      return;
    }
    const cost = bucks * POINTS_PER_REAL_BUCK;
    if (cost > balances.points) {
      setConvertError(
        `That takes ${cost} Points — you have ${balances.points}. Earn more by playing, or convert fewer Bucks.`
      );
      setConvertNote(null);
      return;
    }
    const next = convertPointsToRealBucks(wallet, bucks);
    if (!next) return; // convertPointsToRealBucks re-checks; unreachable after the guards above
    saveWallet(next);
    setWallet(next);
    setConvertError(null);
    setConvertNote(
      `Converted ${cost} Points → ${bucks} Real Buck${bucks === 1 ? '' : 's'} — worth ${formatUSD(bucks * REAL_BUCK_IN_SYSTEM_CENTS)} inside GLACER, ${formatUSD(bucks * REAL_BUCK_CASH_OUT_CENTS)} cashed out. It's in the ledger below.`
    );
    setConvertInput('1');
  };

  const memberSince = new Date(wallet.createdAt).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
  const stakeTier = balances.totalShareReceivedCents > 0 ? 'Shareholder' : 'Member';

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="wallet-page">
      <Typography variant="h4" gutterBottom align="center">
        GLACER Wallet{' '}
        <Chip
          label="DEMO"
          size="small"
          color="warning"
          sx={{ fontWeight: 'bold', verticalAlign: 'middle' }}
        />
      </Typography>

      {/* The house model — Eddie's standing model, stated to
          customers out loud (his direction, 2026-11-17).
          Round 27 alignment (2026-11-18): this card is the
          PERMANENT home of the first-arrival welcome message
          (design v5 addendum), so it now carries that copy
          VERBATIM — headline, body, small print — and the two
          homes agree word for word. The pre-v5 wording said the
          same model in other words but never stated the $100
          first-cash-out gate (Eddie's rule, decided 2026-11-18);
          the v5 small print does. */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="wallet-house-model">
        <Typography variant="h6" gutterBottom>
          GLACER gives back.
        </Typography>
        <Typography variant="body1" gutterBottom>
          This isn&apos;t just a game — it&apos;s an ecosystem that rewards you for participating.
          Battle, walk, explore, meet people: playing earns you Points. Points turn into perks or
          Real Bucks — real money you can spend here or cash out. And every month, GLACER shares
          part of what it earns with the players who showed up. Your share is our way of saying
          thanks for helping GLACER grow.
        </Typography>
        <Typography variant="body2">
          Real Bucks are worth $1.25 when you spend them in GLACER, or $1.00 cashed out. Cash out
          unlocks once your balance reaches $100.
        </Typography>
      </Paper>

      <Paper sx={{ p: 2, mb: 3 }} data-testid="wallet-demo-banner">
        <Typography variant="body2" color="text.secondary">
          <strong>Demo wallet.</strong> Payments aren&apos;t connected yet — connecting the payment
          rail needs Eddie&apos;s separate approval — so every balance here is fictional, lives on
          this device only, and no real money can move. The shape is the real design: one ledger,
          every movement named and dated.
        </Typography>
      </Paper>

      {/* The loop principle as two totals. */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Box sx={{ display: 'flex', gap: 3, flexWrap: 'wrap' }}>
          <Box>
            <Typography variant="caption" color="text.secondary">
              TOTAL INSIDE GLACER
            </Typography>
            <Typography variant="h5" sx={{ fontWeight: 800 }} data-testid="wallet-total-in-system">
              {formatUSD(balances.inSystemCents)}
            </Typography>
          </Box>
          <Box>
            <Typography variant="caption" color="text.secondary">
              TOTAL CASHED OUT
            </Typography>
            <Typography variant="h5" sx={{ fontWeight: 800 }} data-testid="wallet-total-cash-out">
              {formatUSD(balances.cashOutCents)}
            </Typography>
          </Box>
          <Box sx={{ alignSelf: 'center' }}>
            <Typography variant="body2" color="text.secondary">
              The gap between the two totals is the stay-in bonus — Real Bucks count at{' '}
              {formatUSD(REAL_BUCK_IN_SYSTEM_CENTS)} in here, {formatUSD(REAL_BUCK_CASH_OUT_CENTS)}{' '}
              out there.
            </Typography>
          </Box>
        </Box>
      </Paper>

      <Section
        title="⭐ Points"
        testId="wallet-section-points"
        balanceTestId="wallet-points-balance"
        balance={`${balances.points} Points`}
      >
        <Typography variant="body2" color="text.secondary">
          What playing pays: battles, Stroll walking, encounters, venue check-ins, meetups and
          referrals all earn Points. Spend them on perks — useful real-world things; GLACER&apos;s
          perk shelf is being defined with the venue program — or convert them to Real Bucks below.
        </Typography>
      </Section>

      <Section
        title="💵 Deposited"
        testId="wallet-section-deposited"
        balanceTestId="wallet-deposited-balance"
        balance={formatUSD(balances.depositedCents)}
      >
        <Typography variant="body2" color="text.secondary" gutterBottom>
          Money you put in. It stays refundable to the payment method it came from, and it is never
          taxed as income — it&apos;s yours, held for spending inside GLACER.
        </Typography>
        <Button
          variant="outlined"
          size="small"
          data-testid="wallet-deposit-button"
          onClick={() => setClosedDoor('deposit')}
        >
          Add money
        </Button>
      </Section>

      <Section
        title="🧾 Earnings"
        testId="wallet-section-earnings"
        balanceTestId="wallet-earnings-balance"
        balance={formatUSD(balances.earningsCents)}
      >
        <Typography variant="body2" color="text.secondary">
          Money other players pay you — selling a navitar from your profile settles here. It is
          income (taxable), it can be cashed out once you&apos;re verified, and it can&apos;t be
          refunded to a card.
        </Typography>
      </Section>

      <Section
        title="🌱 Your Share"
        testId="wallet-section-share"
        balanceTestId="wallet-share-balance"
        balance={formatUSD(balances.shareCents)}
      >
        <Typography variant="body2" color="text.secondary">
          Money GLACER pays you out of its own revenue — thanks for helping GLACER grow. It is
          income (taxable) and cashable out once you&apos;re verified. The share rate is
          Eddie&apos;s call, set before the pool opens — no number is promised here until he sets
          it.
        </Typography>
      </Section>

      <Paper sx={{ p: 3, mb: 3 }} data-testid="wallet-section-ownership">
        <Typography variant="h6" gutterBottom>
          👑 Ownership
        </Typography>
        <Typography variant="body2" color="text.secondary" gutterBottom>
          Being a user carries ownership. This is your stake — an in-world share and status, yours
          for being here. It isn&apos;t stock and it isn&apos;t a security; it&apos;s how GLACER
          says the players own a piece of what they&apos;re building.
        </Typography>
        <Typography variant="body1">
          Member since <strong data-testid="wallet-member-since">{memberSince}</strong>{' '}
          <Typography component="span" variant="body2" color="text.secondary">
            (on this device — the account date arrives with the backend)
          </Typography>
        </Typography>
        <Typography variant="body1">
          Stake tier: <strong data-testid="wallet-stake-tier">{stakeTier}</strong>
        </Typography>
        <Typography variant="body1">
          Total share received, all time:{' '}
          <strong data-testid="wallet-total-share-received">
            {formatUSD(balances.totalShareReceivedCents)}
          </strong>
        </Typography>
      </Paper>

      {/* The converter — the one door that works today, locally. */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="wallet-converter">
        <Typography variant="h6" gutterBottom>
          🔄 Convert Points → Real Bucks
        </Typography>
        <Typography variant="body2" color="text.secondary" gutterBottom>
          {POINTS_PER_REAL_BUCK} Points = 1 Real Buck. A Real Buck is worth{' '}
          {formatUSD(REAL_BUCK_IN_SYSTEM_CENTS)} spent inside GLACER and{' '}
          {formatUSD(REAL_BUCK_CASH_OUT_CENTS)} cashed out — keeping it in the loop pays more, by
          design. Conversion is one-way: Real Bucks never turn back into Points.
        </Typography>
        <Typography variant="body1" gutterBottom>
          Your Real Bucks:{' '}
          <strong data-testid="wallet-realbucks-balance">{balances.realBucks}</strong>
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-start', flexWrap: 'wrap' }}>
          <TextField
            size="small"
            type="number"
            label="Real Bucks"
            value={convertInput}
            onChange={e => setConvertInput(e.target.value)}
            data-testid="wallet-convert-input"
            inputProps={{ min: 1, step: 1 }}
            sx={{ width: 140 }}
          />
          <Button variant="contained" data-testid="wallet-convert-button" onClick={handleConvert}>
            Convert
          </Button>
        </Box>
        {convertError && (
          <Typography
            variant="body2"
            color="error"
            sx={{ mt: 1 }}
            data-testid="wallet-convert-error"
          >
            {convertError}
          </Typography>
        )}
        {convertNote && (
          <Typography variant="body2" sx={{ mt: 1 }} data-testid="wallet-convert-note">
            {convertNote}
          </Typography>
        )}
        <Box sx={{ mt: 2 }}>
          <Button
            variant="outlined"
            size="small"
            data-testid="wallet-cashout-button"
            onClick={() => setClosedDoor('cashout')}
          >
            Cash out
          </Button>
        </Box>
      </Paper>

      {/* The ledger — the wallet is this list, rendered. */}
      <Typography variant="h5" gutterBottom>
        Ledger
      </Typography>
      <Box
        sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, mb: 3 }}
        data-testid="wallet-ledger"
      >
        {[...wallet.entries].reverse().map(e => (
          <Paper key={e.id} sx={{ p: 2 }} data-testid="wallet-ledger-entry">
            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                {e.label}
              </Typography>
              {e.demo && <Chip size="small" variant="outlined" label="DEMO" sx={{ height: 18 }} />}
            </Box>
            <Typography variant="body2" color="text.secondary">
              {entryDeltaSummary(e)} ·{' '}
              {new Date(e.ts).toLocaleDateString(undefined, {
                year: 'numeric',
                month: 'short',
                day: 'numeric',
              })}
            </Typography>
          </Paper>
        ))}
      </Box>

      {/* Closed-door dialog: deposits and cash-outs are not
          executable until the rail connects. Explaining that —
          and changing NO state — is the feature, exactly like
          Round 19's Buy dialog. */}
      <Dialog
        open={closedDoor !== null}
        onClose={() => setClosedDoor(null)}
        data-testid="wallet-not-connected-dialog"
        fullWidth
        maxWidth="xs"
      >
        <DialogTitle>
          {closedDoor === 'cashout' ? 'Cash out' : 'Add money'}{' '}
          <Chip label="DEMO" size="small" color="warning" sx={{ fontWeight: 'bold' }} />
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary">
            {closedDoor === 'cashout' ? (
              <>
                Cashing out opens when payments are connected. The payment rail needs Eddie&apos;s
                separate approval before it connects, so for now nothing can leave the wallet — and
                this tap changed nothing. When it opens, verified players will cash out Earnings,
                Your Share and Real Bucks to their bank; unverified players can still hold and spend
                inside GLACER.
              </>
            ) : (
              <>
                Adding money opens when payments are connected. The payment rail needs Eddie&apos;s
                separate approval before it connects, so no card can be charged and no deposit can
                be taken yet — and this tap changed nothing. When it opens, money you put in lands
                in Deposited, refundable to the method it came from.
              </>
            )}
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button
            variant="contained"
            onClick={() => setClosedDoor(null)}
            data-testid="wallet-not-connected-close"
          >
            Got it
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default Wallet;
