import React from 'react';
import { Box, Button, ButtonGroup, Typography, Grid, Paper, Chip } from '@mui/material';
import { styled } from '@mui/material/styles';
import { NavitarArtImg } from './NavitarArtImg';
import { ModelViewer } from './ModelViewer';
import { PowerTracker } from './PowerTracker';
import { getCollectibleCard } from '../utils/collectibleCards';
import { elementEmoji } from '../utils/navitarArt';
import { playNavitarCry } from '../utils/sound';
import { motionSignatureFor } from '../utils/motionSignature';
import BattleWithButton, {
  ChooseCheckButton,
  ChooseLockButton,
  lockReasonFor,
  useChooseNavitar,
} from './BattleWithButton';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';

export interface NavitarDesignProps {
  type:
    'ice' | 'fire' | 'nature' | 'shadow' | 'light' | 'quantum' | 'electric' | 'spiritual' | 'water';
  name: string;
  // Optional for the same reason rarity/stats are: a locked design
  // (see utils/lockedRoster.ts) has no roster level yet, so the Lv.
  // chip hides rather than inventing one.
  level?: number;
  // Optional: a navitar without roster data omits them, and the chip
  // and stat bars are hidden when absent — nothing is invented. (The
  // two bar-loop fighters, Griffin and Ashwing, carry display-default
  // stats so their cards match the roster's — see NavitarShowcase.)
  rarity?: 'common' | 'rare' | 'epic' | 'legendary';
  stats?: {
    health: number;
    attack: number;
    defense: number;
    speed: number;
  };
  // Card lore (Eddie, 2026-11-13): shown on the card's Lore tab,
  // next to the Stats tab that carries the stat block above. Sourced
  // from NAVITAR_LORE (utils/navitarArt.ts) by the records that pass
  // stats; a card without lore keeps the plain stat block, no tabs.
  lore?: string;
  // Art image served from public/navitars/. When absent the card keeps the
  // type-coloured gradient as the visual (the 5 original navitars have no
  // art yet — nothing is invented for them).
  imageUrl?: string;
  // Locked treatment (Eddie's roster-scaling decision, 2026-11-13):
  // a designed navitar that is NOT in the playable stage roster is
  // visible but untouchable. The card renders darkened/silhouetted
  // with a 🔒 LOCKED chip and the unlock-path line (unlockLabel,
  // from utils/lockedRoster.ts). Stats/Lore stay viewable where they
  // exist — visible is the point — and the battle selection logic
  // refuses it (NavitarBattle / NavitarFightClub enforce via
  // isLockedNavitar). A locked PRIME card may carry a view-only
  // modelUrl for the 2D/3D toggle below; Batch/Mystic/Deity locked
  // cards carry none.
  locked?: boolean;
  unlockLabel?: string;
  // Collection-design data (owner-mode full collection): the design's
  // tier and signature ability name from the collection file. Shown
  // in place of stat bars on cards that carry NO stats — stats are
  // never fabricated for a design; a missing tier/ability renders
  // as an honest "—".
  tier?: string;
  abilityName?: string;
  // The design has no portrait yet: the element placeholder on this
  // card is a data gap, not a lock — labelled PLACEHOLDER ART so it
  // is never mistaken for locked styling.
  placeholderArt?: boolean;
  // GLB served from public/models/. When present the card gets the
  // 2D / 3D toggle over the art slot (restored 2026-11-13 on Eddie's
  // call — "bring back the 3-D model toggle" — reversing the
  // 2026-11-12 battles-only removal; the original implementation
  // shipped 2026-11-11 and is restored faithfully). The 3D view is
  // VIEW-ONLY and lazy: ModelViewer mounts only when the toggle is
  // flipped, so no model is fetched on page load, and the view
  // degrades to the 2D art if the renderer cannot mount. On a LOCKED
  // card (the Primes) the toggle changes nothing about selection —
  // the lock stays on in both views; looking is not playing.
  modelUrl?: string;
  // Closer framing for the 3D model (1 = default; the phoenix's wide
  // wingspan needs 1.5 to read at a good size in the card).
  modelZoom?: number;
  // Navidex surfaces pass this: a clear "Battle with <name>" action
  // at the card's foot (Eddie, 2026-11-16) — sets the battle
  // navitar and goes to /battle. Never rendered on locked cards.
  battleAction?: boolean;
  // Round 24 (Eddie, 2026-11-18): the Navidex Card view's picture
  // is the fighter's COLLECTIBLE CARD artwork (utils/collectible
  // Cards) when one exists — the picture is visual only; the stats
  // and lore below stay live from this card's data. Opt-in per
  // surface: NavitarShowcase passes it for the Navidex grids, so
  // other surfaces rendering this card (Home's Featured strip)
  // keep the portrait exactly as before. Locked cards never get
  // it — their silhouette treatment is untouched.
  collectibleArt?: boolean;
  // Round 25 (Eddie, 2026-11-18): the UNIFORM frame. Navidex grid
  // surfaces pass this so every card is ONE standard size and every
  // picture renders at ONE standard size/scale: the picture slot
  // takes the collectible canvas's own aspect (5:7) instead of the
  // old fixed 200px height — the 5:7 card art fills it exactly,
  // portraits letterbox whole inside the same frame, and the locked
  // silhouette centers in it (lock treatment unchanged). The card
  // itself stretches to fill its grid cell (the Navidex grids size
  // every cell identically), so card boxes match too. Surfaces that
  // don't pass it (Home's Featured strip) render exactly as before.
  uniformFrame?: boolean;
  // Navidex grid surfaces pass this (Eddie, 2026-11-16 ~13:46 PT):
  // the ✓ check on the card art — "that's where you pick your
  // avatar right there. Click the check and it takes over the role
  // of being with you." Renders only where choosing is actually
  // possible (owned only since Round 16, via useChooseNavitar — the same
  // write path as the Stage's Choose button) and never on locked
  // cards. Other surfaces that render this card (Home) don't pass
  // it, so their cards stay check-free.
  chooseCheck?: boolean;
  // Round 30 (Eddie, 2026-11-18): the trading-card info strip
  // under the art carries the fighter's Navidex number and
  // epithet where the collection data records them (owner
  // designs, and the showcase heroes via their collection
  // entries). Absent data stays absent — the strip falls back
  // to the element line alone; no number is ever invented.
  navidexNum?: number;
  epithet?: string;
}

const NavitarCard = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(2),
  borderRadius: theme.shape.borderRadius * 2,
  background: `linear-gradient(135deg, ${theme.palette.background.paper} 0%, ${theme.palette.background.default} 100%)`,
  boxShadow: theme.shadows[4],
  position: 'relative',
  overflow: 'hidden',
  '&::before': {
    content: '""',
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '4px',
    background: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.5), transparent)',
  },
}));

const StatBar = styled(Box)(({ theme }) => ({
  height: '8px',
  borderRadius: '4px',
  background: theme.palette.grey[200],
  position: 'relative',
  overflow: 'hidden',
  '&::after': {
    content: '""',
    position: 'absolute',
    top: 0,
    left: 0,
    height: '100%',
    background: theme.palette.primary.main,
    borderRadius: '4px',
  },
}));

const getTypeColor = (type: string) => {
  switch (type) {
    case 'ice':
      return '#81D4FA';
    case 'fire':
      return '#FF5722';
    case 'nature':
      return '#4CAF50';
    case 'shadow':
      return '#9C27B0';
    case 'light':
      return '#FFC107';
    case 'quantum':
      return '#B388FF';
    case 'electric':
      return '#FFEA00';
    case 'spiritual':
      return '#80DEEA';
    case 'water':
      return '#2196F3';
    default:
      return '#2196F3';
  }
};

const getRarityColor = (rarity: string) => {
  switch (rarity) {
    case 'legendary':
      return '#FFD700';
    case 'epic':
      return '#9C27B0';
    case 'rare':
      return '#2196F3';
    default:
      return '#4CAF50';
  }
};

export const NavitarDesign: React.FC<NavitarDesignProps> = ({
  type,
  name,
  level,
  rarity,
  stats,
  lore,
  imageUrl,
  locked,
  unlockLabel,
  tier,
  abilityName,
  placeholderArt,
  modelUrl,
  modelZoom = 1,
  battleAction,
  chooseCheck,
  collectibleArt,
  uniformFrame,
  navidexNum,
  epithet,
}) => {
  // Stats / Lore tabs (Eddie, 2026-11-13): Stats is the card's
  // original stat block, unchanged and shown by default; Lore swaps
  // it for the dossier text. Only rendered when the card carries
  // lore — a lore-less card looks exactly as it did before.
  const [cardTab, setCardTab] = React.useState<'stats' | 'lore'>('stats');
  // This fighter's motion signature (Eddie, 2026-11-16) — drives
  // the art's idle animation vars below; the Stage uses the same
  // signature for the 3D presentation.
  const cardSig = motionSignatureFor(name, type);
  // 2D / 3D toggle (restored 2026-11-13): 2D by default; the 3D
  // viewer mounts only on flip, so the model loads lazily.
  const [show3d, setShow3d] = React.useState(false);
  // Chosen state from the SAME source of truth the Choose button
  // writes (FightClub userNavitar / glacer-active-navitar-id) —
  // read-only here, no parallel selection state. Locked cards can
  // never be chosen.
  const { navitars: ownedFighters, userNavitar } = useNavitarFightClub();
  const isChosen =
    !locked && !!userNavitar && ownedFighters.some(n => n.id === userNavitar.id && n.name === name);
  // The ✓ check's eligibility, from the SAME choose path the
  // check itself writes through (BattleWithButton's hook): the
  // check renders only where a tap can really choose — and the
  // Lv chip makes room for it only when it's actually there.
  const { canChoose } = useChooseNavitar(name, type, imageUrl);
  const showCheck = !!chooseCheck && !locked && canChoose;
  // Round 16 (Eddie, 2026-11-17): owned-only selection — a card
  // whose fighter is NOT in the player's collection shows the
  // lock treatment in the check's seat instead of a working ✓:
  // the lock button (tap → the reason, below), the NOT IN YOUR
  // COLLECTION chip, and no choose write of any kind. The card
  // itself — art, stats, lore — stays fully readable: the roster
  // is for browsing, choosing is for owners. (The locked-roster
  // cards above this in the file are a different, harder seal —
  // the `locked` prop — and are untouched.)
  const showLock = !!chooseCheck && !locked && !canChoose;
  const [lockNoteOpen, setLockNoteOpen] = React.useState(false);
  // Round 24: this fighter's collectible card artwork, when this
  // surface opted in (collectibleArt) and a card exists for it.
  // Null otherwise — the card renders its portrait exactly as
  // before. (Callers never pass the opt-in on locked cards; the
  // render branch still applies the locked grayscale if one did.)
  const cardArtUrl = collectibleArt ? getCollectibleCard(name) : null;
  // The stat block (HP / ATK / DEF / SPD bars + values) — ONE
  // block shared by the classic body (under its Stats tab) and
  // the Round 30 trading-card body (always on the card face), so
  // the two presentations can never drift apart in values or
  // order.
  const statsBlock = stats ? (
    <Grid container spacing={1}>
      <Grid item xs={12}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="body2" sx={{ width: '60px' }}>
            HP
          </Typography>
          <StatBar sx={{ flex: 1, '&::after': { width: `${(stats.health / 100) * 100}%` } }} />
          <Typography variant="body2">{stats.health}</Typography>
        </Box>
      </Grid>
      <Grid item xs={12}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="body2" sx={{ width: '60px' }}>
            ATK
          </Typography>
          <StatBar sx={{ flex: 1, '&::after': { width: `${(stats.attack / 100) * 100}%` } }} />
          <Typography variant="body2">{stats.attack}</Typography>
        </Box>
      </Grid>
      <Grid item xs={12}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="body2" sx={{ width: '60px' }}>
            DEF
          </Typography>
          <StatBar sx={{ flex: 1, '&::after': { width: `${(stats.defense / 100) * 100}%` } }} />
          <Typography variant="body2">{stats.defense}</Typography>
        </Box>
      </Grid>
      <Grid item xs={12}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="body2" sx={{ width: '60px' }}>
            SPD
          </Typography>
          <StatBar sx={{ flex: 1, '&::after': { width: `${(stats.speed / 100) * 100}%` } }} />
          <Typography variant="body2">{stats.speed}</Typography>
        </Box>
      </Grid>
    </Grid>
  ) : null;
  return (
    <NavitarCard
      data-navitar-name={name}
      data-locked={locked ? 'true' : undefined}
      data-chosen={isChosen ? 'true' : undefined}
      sx={{
        // Round 25: uniform-frame cards fill their (identically
        // sized) grid cell, so every card box in the Navidex grid
        // is the same size.
        ...(uniformFrame
          ? { height: '100%', display: 'flex', flexDirection: 'column' as const }
          : {}),
        // Round 30 trading-card dress (uniform/Navidex cards
        // only): an element-tinted body wash and an element
        // frame ring around the whole card — the Donphan card's
        // type-coloured body + border, in GLACER's own palette.
        // Painted with background/box-shadow ONLY: neither moves
        // the card box or the picture slot by a pixel (the R25
        // uniformity measurements stand). The chosen card's gold
        // treatment below overrides the ring, as before.
        ...(uniformFrame
          ? {
              background: `linear-gradient(165deg, ${getTypeColor(type)}38 0%, ${getTypeColor(type)}14 46%, rgba(140,170,185,0.10) 82%)`,
              boxShadow: `0 0 0 3px ${getTypeColor(type)}d9, 0 10px 26px rgba(0,0,0,0.20)`,
            }
          : {}),
        ...(isChosen
          ? {
              outline: '3px solid #ffd54f',
              outlineOffset: -3,
              boxShadow: '0 0 0 2px rgba(255,213,79,0.4), 0 0 28px rgba(255,213,79,0.55)',
            }
          : {}),
      }}
    >
      {modelUrl && (
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
          <ButtonGroup size="small" aria-label={`${name} view toggle`}>
            <Button
              variant={show3d ? 'outlined' : 'contained'}
              aria-label={`Show Card view of ${name}`}
              aria-pressed={!show3d}
              onClick={() => setShow3d(false)}
            >
              Card
            </Button>
            <Button
              variant={show3d ? 'contained' : 'outlined'}
              aria-label={`Show 3D model of ${name}`}
              aria-pressed={show3d}
              onClick={() => setShow3d(true)}
            >
              3D
            </Button>
          </ButtonGroup>
        </Box>
      )}
      {/* HEADER BAND (Round 30, uniform/Navidex cards only): the
          trading-card header — the fighter's name big and bold,
          its rarity/tier tag above it (the reference card's stage
          tag seat), and at the right the HP value with the
          element mark in a coloured disc. Every value is the
          card's own data, moved — not changed: the HP is the
          same stats.health the stat rows show, the tag is the
          same rarity/tier the classic body shows. A card with
          no stats shows no HP (nothing is invented), and a card
          with neither rarity nor tier shows no tag. */}
      {uniformFrame && (
        <Box
          sx={{
            display: 'flex',
            alignItems: 'flex-start',
            justifyContent: 'space-between',
            gap: 1,
            mb: 1.5,
          }}
        >
          <Box sx={{ minWidth: 0 }}>
            {(rarity || tier) && (
              <Chip
                data-testid="card-header-tag"
                label={(rarity ?? tier)!.toUpperCase()}
                size="small"
                sx={{
                  height: 18,
                  fontSize: '0.6rem',
                  fontWeight: 900,
                  letterSpacing: '0.06em',
                  bgcolor: rarity ? getRarityColor(rarity) : 'rgba(0,0,0,0.55)',
                  color: 'white',
                  mb: 0.5,
                }}
              />
            )}
            <Typography variant="h6" sx={{ fontWeight: 800, lineHeight: 1.15 }}>
              {name}
            </Typography>
          </Box>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexShrink: 0 }}>
            {stats && (
              <Box sx={{ textAlign: 'right' }}>
                <Typography
                  variant="caption"
                  sx={{
                    display: 'block',
                    fontWeight: 900,
                    letterSpacing: '0.08em',
                    color: 'text.secondary',
                    lineHeight: 1,
                  }}
                >
                  HP
                </Typography>
                <Typography
                  data-testid="card-header-hp"
                  sx={{ fontWeight: 900, fontSize: '1.35rem', lineHeight: 1.05 }}
                >
                  {stats.health}
                </Typography>
              </Box>
            )}
            <Box
              aria-label={`${type} element`}
              sx={{
                width: 34,
                height: 34,
                borderRadius: '50%',
                bgcolor: getTypeColor(type),
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '18px',
                boxShadow: 'inset 0 0 0 2px rgba(255,255,255,0.55), 0 2px 6px rgba(0,0,0,0.25)',
              }}
            >
              {elementEmoji(type)}
            </Box>
          </Box>
        </Box>
      )}
      <Box sx={{ position: 'relative', mb: 2 }}>
        {/* Navitar visual — the art image when one exists, otherwise
            the type-coloured gradient with the pulsing glow. */}
        <Box
          className="glacer-amb-card"
          // Idle SIGNATURE on the art (Eddie, 2026-11-16): the
          // card's img animates with this fighter's own motion
          // style — modern.css reads the vars (--sig-card-anim /
          // -dur / -delay), set from the same deterministic
          // signature the Stage uses, a touch slower so the grid
          // stays calm. Locked cards are stilled by the
          // [data-locked] rule regardless.
          style={
            {
              '--sig-card-anim': `glacer-card-${cardSig.style}`,
              '--sig-card-dur': `${(cardSig.durationS + 2.5).toFixed(1)}s`,
              '--sig-card-delay': `${cardSig.delayS}s`,
              // Round 25: the uniform picture frame — the slot IS
              // the collectible canvas shape (5:7), so the picture
              // renders at one standard size on every card.
              ...(uniformFrame ? { aspectRatio: '5 / 7' } : {}),
            } as React.CSSProperties
          }
          onClick={() => {
            // Tapping a fighter's art: its element-flavored cry
            // (synth sound identity, utils/sound.ts). Locked cards
            // stay silent — sealed is sealed.
            if (!locked) playNavitarCry(type);
          }}
          sx={{
            width: '100%',
            // Round 25: uniform-frame slots size by aspect (above)
            // instead of the old fixed height.
            height: uniformFrame ? 'auto' : '200px',
            background: locked
              ? `linear-gradient(135deg, ${getTypeColor(type)}26, rgba(0,0,0,0.45))`
              : `linear-gradient(135deg, ${getTypeColor(type)}40, ${getTypeColor(type)}20)`,
            borderRadius: '16px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            position: 'relative',
            overflow: 'hidden',
            // Round 30: the framed art window's outer edge — an
            // element-coloured ring around the slot, painted as
            // shadow so the slot's measured size (R25) is exact.
            ...(uniformFrame
              ? { boxShadow: `0 0 0 3px ${getTypeColor(type)}, 0 6px 18px rgba(0,0,0,0.22)` }
              : {}),
          }}
        >
          {/* Realm Elements rule (Eddie, Round 30, 2026-11-18):
              the card presents CLEAN — the element drips/particles
              (the Realm Elements) belong to the loaded 3D
              character and do NOT run inside or behind the card,
              on any surface (grid, summon veil, Profile). The
              in-card ElementalAmbience layer that rendered here
              since Round 1 is removed under this rule; the art
              itself keeps its light idle signature (CSS,
              modern.css) — that is the picture's own motion, not
              background graphics. Locked cards stay locked and
              still. */}
          {show3d && modelUrl ? (
            <ModelViewer
              modelUrl={modelUrl}
              zoom={modelZoom}
              fallbackSrc={imageUrl}
              fallbackAlt={`${name} — 3D preview`}
              element={type}
              fighterName={name}
              height="100%"
            />
          ) : cardArtUrl ? (
            /* Round 24: the collectible card IS the picture on the
               Navidex (collectibleArt surfaces). Shown whole —
               contain fit on the slot's gradient, never cropped —
               standing in the slot like the physical card it is.
               The locked grayscale treatment still applies if a
               locked card ever carries art this way. */
            <NavitarArtImg
              src={cardArtUrl}
              alt={`${name} collectible card`}
              element={type}
              fit="contain"
              style={{
                width: '100%',
                height: '100%',
                ...(locked ? { filter: 'grayscale(75%) brightness(0.5)' } : {}),
              }}
            />
          ) : imageUrl ? (
            <NavitarArtImg
              src={imageUrl}
              alt={name}
              element={type}
              fit="contain"
              style={{
                width: '100%',
                height: '100%',
                ...(locked ? { filter: 'grayscale(75%) brightness(0.5)' } : {}),
              }}
            />
          ) : locked ? (
            /* Locked with no portrait: a silhouette — the element
               glyph rendered solid black over the darkened element
               gradient. Mystics are silhouette-first by design law;
               the other locked designs simply have no art yet, and
               nothing is invented for them. */
            <Box
              aria-hidden
              sx={{
                fontSize: '110px',
                lineHeight: 1,
                filter: 'brightness(0)',
                opacity: 0.55,
                userSelect: 'none',
              }}
            >
              {elementEmoji(type)}
            </Box>
          ) : (
            <Box
              sx={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                width: '120px',
                height: '120px',
                borderRadius: '50%',
                background: `radial-gradient(circle, ${getTypeColor(type)}20, transparent)`,
                animation: 'pulse 2s infinite',
                '@keyframes pulse': {
                  '0%': { transform: 'translate(-50%, -50%) scale(1)' },
                  '50%': { transform: 'translate(-50%, -50%) scale(1.2)' },
                  '100%': { transform: 'translate(-50%, -50%) scale(1)' },
                },
              }}
            />
          )}

          {/* ART FRAME (Round 30, uniform/Navidex cards only):
              the silvered inner frame of the trading-card art
              window — an inset ring + soft inner shade over the
              art's edge, like the printed frame on the reference
              card. Purely visual: pointer-events none, painted
              above the art (zIndex 2) and below the chips (3)
              and the ✓ check (5), and it covers nothing the
              never-crop law protects — the fighter stays whole
              inside it. Locked cards wear it over the silhouette
              exactly the same; nothing is revealed. */}
          {uniformFrame && (
            <Box
              aria-hidden
              sx={{
                position: 'absolute',
                inset: 0,
                borderRadius: '16px',
                zIndex: 2,
                pointerEvents: 'none',
                boxShadow:
                  'inset 0 0 0 3px rgba(244,249,252,0.95), inset 0 0 0 6px rgba(8,20,30,0.35), inset 0 0 34px rgba(0,0,0,0.28)',
              }}
            />
          )}

          {/* CHOSEN badge — painted above the art in this
              positioned box; the gold ring on the card itself
              carries the same signal. */}
          {isChosen && (
            <Chip
              label="✓ CHOSEN"
              size="small"
              sx={{
                position: 'absolute',
                bottom: 8,
                left: 8,
                zIndex: 3,
                bgcolor: '#ffd54f',
                color: '#4a3500',
                fontWeight: 900,
                boxShadow: '0 0 14px rgba(255,213,79,0.8)',
              }}
            />
          )}

          {/* LOCKED chip — the untouchable marker, over the art. */}
          {locked && (
            <Chip
              label="🔒 LOCKED"
              size="small"
              sx={{
                position: 'absolute',
                bottom: 8,
                left: 8,
                bgcolor: 'rgba(0,0,0,0.78)',
                color: '#FFD700',
                fontWeight: 'bold',
                border: '1px solid rgba(255,215,0,0.55)',
              }}
            />
          )}

          {/* The ✓ CHECK (Eddie, 2026-11-16 ~13:46 PT) — top
              corner of the card art: "that's where you pick your
              avatar right there." Tapping it chooses this navitar
              through the one choose path (useChooseNavitar →
              glacer-active-navitar-id); the chosen card's check
              fills gold, matching the ring + CHOSEN badge. Above
              the ambience and the 3D viewer (which fills this same
              box), below nothing interactive. */}
          {showCheck && (
            <Box sx={{ position: 'absolute', top: 6, right: 6, zIndex: 5 }}>
              <ChooseCheckButton
                name={name}
                element={type}
                imageUrl={imageUrl}
                // Round 7 sound restore: the check's click
                // stopPropagation()s the card art's cry (by
                // design — a pick is not an art tap), but Round 6
                // passed no onChosen, so choosing from the grid
                // was SILENT while the Stage's check answers with
                // the victory flourish + cry. The chosen fighter
                // now answers here too, with its own cry.
                onChosen={() => playNavitarCry(type)}
              />
            </Box>
          )}

          {/* The LOCK in the check's seat (Round 16): an unowned
              fighter's card carries the lock where the ✓ would
              sit, plus its state chip where the LOCKED chip sits
              on sealed cards. Tapping the lock opens the reason
              under the art — it never chooses anything. */}
          {showLock && (
            <>
              <Box sx={{ position: 'absolute', top: 6, right: 6, zIndex: 5 }}>
                <ChooseLockButton name={name} onTap={() => setLockNoteOpen(o => !o)} />
              </Box>
              <Chip
                label="🔒 NOT IN YOUR COLLECTION"
                size="small"
                sx={{
                  position: 'absolute',
                  bottom: 8,
                  left: 8,
                  zIndex: 3,
                  bgcolor: 'rgba(0,0,0,0.78)',
                  color: '#FFD700',
                  fontWeight: 'bold',
                  border: '1px solid rgba(255,215,0,0.55)',
                }}
              />
            </>
          )}
        </Box>

        {/* The lock's reason (Round 16): shown when the player
            taps the lock — why this fighter can't be chosen and
            how a fighter becomes theirs, in the game's own terms. */}
        {showLock && lockNoteOpen && (
          <Typography
            variant="body2"
            data-lock-note={name}
            sx={{ mb: 2, fontWeight: 'bold', color: 'text.secondary' }}
          >
            🔒 {lockReasonFor(name)}
          </Typography>
        )}

        {/* Level Badge — hidden when the navitar has no level yet
            (locked designs carry none; nothing is invented).
            Round 30: on uniform/Navidex cards the level rides
            the power tracker at the card's foot instead, so this
            overlay is classic-body only. */}
        {!uniformFrame && level !== undefined && (
          <Chip
            label={`Lv. ${level}`}
            size="small"
            sx={{
              position: 'absolute',
              top: 8,
              // When the ✓ check (or the Round 16 lock in its
              // seat) sits on the art's top corner, the Lv chip
              // slides left to make room for it.
              right: showCheck || showLock ? 58 : 8,
              bgcolor: 'rgba(0,0,0,0.6)',
              color: 'white',
              fontWeight: 'bold',
            }}
          />
        )}

        {/* Rarity Badge — hidden when the navitar has no rarity yet.
            Round 30: on uniform/Navidex cards the rarity rides
            the header band's tag instead (same value, moved). */}
        {!uniformFrame && rarity && (
          <Chip
            label={rarity.toUpperCase()}
            size="small"
            sx={{
              position: 'absolute',
              top: 8,
              left: 8,
              bgcolor: getRarityColor(rarity),
              color: 'white',
              fontWeight: 'bold',
            }}
          />
        )}

        {/* Placeholder-art label — the design simply has no portrait
            yet (owner collection). NOT a lock: no lock styling, the
            card stays fully usable. Round 25: a design WITH
            collectible card art is not a placeholder anymore — the
            chip only labels the gradient that truly has no art. */}
        {placeholderArt && !imageUrl && !cardArtUrl && (
          <Chip
            label="PLACEHOLDER ART"
            size="small"
            sx={{
              position: 'absolute',
              bottom: 8,
              right: 8,
              bgcolor: 'rgba(0,0,0,0.55)',
              color: 'rgba(255,255,255,0.85)',
              fontWeight: 'bold',
              letterSpacing: '0.04em',
            }}
          />
        )}
      </Box>

      {/* INFO STRIP (Round 30, uniform/Navidex cards only): the
          silver strip under the reference card's art window —
          "№ 232 · Armor Pokémon · HT · WT" in its grammar, but
          carrying ONLY what this fighter's data actually
          records: its Navidex number and epithet where the
          collection data has them, and the element line always
          (the element is the card's own type). No number, no
          species, no measurements are invented for a fighter
          whose data doesn't carry them. */}
      {uniformFrame && (
        <Box
          data-testid="card-info-strip"
          sx={{
            mb: 2,
            px: 1,
            py: 0.5,
            borderRadius: '6px',
            textAlign: 'center',
            bgcolor: 'rgba(140,170,185,0.16)',
            border: '1px solid rgba(140,170,185,0.35)',
          }}
        >
          <Typography
            variant="caption"
            sx={{
              fontStyle: 'italic',
              letterSpacing: '0.04em',
              color: 'text.secondary',
              fontWeight: 600,
            }}
          >
            {[
              navidexNum !== undefined ? `№ ${navidexNum}` : null,
              epithet ?? null,
              `${type.toUpperCase()} ELEMENT`,
            ]
              .filter(Boolean)
              .join(' · ')}
          </Typography>
        </Box>
      )}

      {/* Classic body heading (non-uniform surfaces — Home's
          Featured strip — render exactly as before; on uniform
          cards the name and element live in the header band). */}
      {!uniformFrame && (
        <>
          <Typography variant="h6" gutterBottom>
            {name}
          </Typography>

          <Chip
            label={type.toUpperCase()}
            size="small"
            sx={{
              bgcolor: getTypeColor(type),
              color: 'white',
              mb: 2,
            }}
          />
        </>
      )}

      {/* Unlock path — how this design joins the playable roster.
          Wording lives with the design's entry in lockedRoster.ts. */}
      {locked && unlockLabel && (
        <Typography variant="body2" sx={{ mb: 2, fontWeight: 'bold', color: 'text.secondary' }}>
          🔒 {unlockLabel}
        </Typography>
      )}

      {uniformFrame ? (
        <>
          {/* ABILITY BLOCK (Round 30): the fighter's signature
              ability as a labelled block on the card face — the
              reference card's "Ability" pill + name, in GLACER's
              own styling. Only the name rides here: it is the
              ability data the card carries (collection designs);
              the ability's text stays where it already lives,
              inside the card's lore line below. A card with no
              recorded ability shows no block. */}
          {abilityName && (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1.5 }}>
              <Chip
                label="ABILITY"
                size="small"
                sx={{
                  height: 22,
                  bgcolor: '#a93226',
                  color: '#fff',
                  fontWeight: 900,
                  fontStyle: 'italic',
                  letterSpacing: '0.05em',
                }}
              />
              <Typography data-testid="card-ability-name" sx={{ fontWeight: 800 }}>
                {abilityName}
              </Typography>
            </Box>
          )}
          {statsBlock}
          {/* LORE AS FLAVOR (Round 30): the fighter's real lore
              on the card face, set in italics at the foot like
              the reference card's flavor text — the same string
              the classic body keeps behind its Lore tab
              (NAVITAR_LORE / the design's composed lore). A
              fighter without written lore shows nothing here;
              no lore is invented. On uniform cards the Stats /
              Lore tabs are gone: the trading card carries both
              on its face, which is the point of the dress. */}
          {lore && (
            <Typography
              data-testid="card-lore-line"
              variant="body2"
              sx={{ fontStyle: 'italic', color: 'text.secondary', lineHeight: 1.55, mt: 1.5 }}
            >
              {lore}
            </Typography>
          )}
        </>
      ) : (
        <>
          {lore && (
            <Box
              sx={{ display: 'flex', gap: 1, mb: 2 }}
              role="tablist"
              aria-label={`${name} card sections`}
            >
              <Chip
                label="Stats"
                size="small"
                role="tab"
                aria-selected={cardTab === 'stats'}
                clickable
                onClick={() => setCardTab('stats')}
                sx={{
                  bgcolor: cardTab === 'stats' ? getTypeColor(type) : 'transparent',
                  color: cardTab === 'stats' ? 'white' : 'text.secondary',
                  border: '1px solid',
                  borderColor: cardTab === 'stats' ? getTypeColor(type) : 'divider',
                  fontWeight: 'bold',
                }}
              />
              <Chip
                label="Lore"
                size="small"
                role="tab"
                aria-selected={cardTab === 'lore'}
                clickable
                onClick={() => setCardTab('lore')}
                sx={{
                  bgcolor: cardTab === 'lore' ? getTypeColor(type) : 'transparent',
                  color: cardTab === 'lore' ? 'white' : 'text.secondary',
                  border: '1px solid',
                  borderColor: cardTab === 'lore' ? getTypeColor(type) : 'divider',
                  fontWeight: 'bold',
                }}
              />
            </Box>
          )}

          {lore && cardTab === 'lore' ? (
            <Typography variant="body2" sx={{ lineHeight: 1.6 }}>
              {lore}
            </Typography>
          ) : (
            statsBlock
          )}

          {/* Design block — owner-collection cards carry no stats (none
          are fabricated); the Stats view shows the design's tier and
          signature ability from the collection file instead, with an
          honest "—" where the file records none. */}
          {(!lore || cardTab === 'stats') && !stats && (tier || abilityName) && (
            <Grid container spacing={1}>
              <Grid item xs={12}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Typography variant="body2" sx={{ width: '60px' }}>
                    TIER
                  </Typography>
                  <Typography variant="body2">{tier ?? '—'}</Typography>
                </Box>
              </Grid>
              <Grid item xs={12}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Typography variant="body2" sx={{ width: '60px' }}>
                    ABILITY
                  </Typography>
                  <Typography variant="body2">{abilityName ?? '—'}</Typography>
                </Box>
              </Grid>
            </Grid>
          )}
        </>
      )}

      {/* POWER TRACKER (Round 30, uniform/Navidex cards only):
          the card's bottom strip — the fighter's level and its
          XP progress bar (PowerTracker reads the same care
          store the Stage care panel uses). Pinned to the card's
          foot (mt: auto in the uniform flex column) so every
          card's tracker sits at the same height. Only a card
          with level data carries one — a design with no level
          shows no tracker rather than an invented one. */}
      {uniformFrame && level !== undefined && (
        <Box sx={{ mt: 'auto', pt: 2 }}>
          <PowerTracker name={name} level={level} />
        </Box>
      )}

      {battleAction && !locked && (
        <BattleWithButton name={name} element={type} imageUrl={imageUrl} />
      )}
    </NavitarCard>
  );
};
