import React, { useEffect, useRef, useState } from 'react';
import { Box, Button, Dialog, DialogContent, LinearProgress, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { WELCOME_SEEN_KEY } from './FirstArrivalWelcome';
import {
  TOUR_REPLAY_EVENT,
  WELCOME_DISMISSED_EVENT,
  markTourDismissed,
  markTourSeen,
  tourAutoShowAllowed,
} from '../utils/tour';

// First-run demo tour (Round 32, Eddie 2026-11-18).
//
// Eddie handed GLACER to a first-time player cold and they were
// confused — so the game introduces itself. The R27 welcome is
// the GREETING (the house model); this tour is the HOW-TO layer
// that follows it: a short step-by-step walk through the core
// loop and the setup basics, in plain player language.
//
// Sequencing law: the tour NEVER stacks on the welcome. It opens
// only once the welcome is resolved — on a fresh device that is
// the moment the welcome is dismissed (FirstArrivalWelcome fires
// WELCOME_DISMISSED_EVENT on every exit path); on a device whose
// welcome was already seen it opens shortly after boot. Skip /
// never-again semantics live in utils/tour.ts: Skip resolves the
// tour, "Stop showing me this" sets the hard never-again flag,
// and the Instructions page can always replay it manually.
//
// Each step is a title, one or two lines, a big visual anchor and
// — where a step is about a place — a "Show me" door that ends
// the tour and takes the player there. Demo framing follows the
// app's existing honesty: simulated people and venues are called
// what they are.

interface TourStep {
  emoji: string;
  title: string;
  body: string;
  door?: { to: string; label: string };
}

const STEPS: TourStep[] = [
  {
    emoji: '🐉',
    title: 'Meet your navitar',
    body: 'Your navitar is your creature companion — it walks beside you everywhere in GLACER. On its Stage in the Navidex, the octagon pad cares for it: Feed it, open its Bag, Train it, Modify its look. A cared-for navitar grows stronger.',
    door: { to: '/collection', label: 'Show me the Navidex' },
  },
  {
    emoji: '✔️',
    title: 'Choose your battle fighter',
    body: 'Tap the gold dot on a fighter in the Navidex to make it your battle navitar. One notification confirms your pick — that fighter is who fights for you everywhere.',
    door: { to: '/collection', label: 'Choose in the Navidex' },
  },
  {
    emoji: '🚶',
    title: 'Stroll — walk the real world',
    body: 'Take your navitar for a walk. Strolling trains it as you go, and wild navitars pop up along the way — meet one, and the fight is yours to accept or pass on.',
    door: { to: '/stroll', label: 'Show me Stroll' },
  },
  {
    emoji: '🗺️',
    title: 'The World Map — heat and perks',
    body: 'The glow on the map is heat: people are around, shown as warmth, never as pins on strangers. Places on the map offer perks — check in when you arrive and see who is here.',
    door: { to: '/map', label: 'Show me the map' },
  },
  {
    emoji: '⚔️',
    title: 'Battle — train, then take challenges',
    body: 'On the Battle screen, Training deals you four opponents matched to your level — and holds How to Fight, the full rules. Challenges from other players land there too. In a duel, the octagon controller throws your moves; the center is your Power Strike.',
    door: { to: '/battle', label: 'Show me Battle' },
  },
  {
    emoji: '🤝',
    title: 'Meet people',
    body: 'GLACER is played with people. Set your status — Open to meet, Battle-ready, Just here, or Invisible — and find players through Networking, Friends and Who\u2019s Here at the places you check in to.',
    door: { to: '/networking', label: 'Show me Networking' },
  },
  {
    emoji: '👛',
    title: 'Your Wallet — GLACER gives back',
    body: 'Playing earns Points. Points turn into perks or Real Bucks — real money you can spend here or cash out. Every month, GLACER shares part of what it earns with the players who showed up.',
    door: { to: '/wallet', label: 'Show me my Wallet' },
  },
  {
    emoji: '💬',
    title: 'Your navitar helps you',
    body: 'Lost? Ask your navitar. Its chat — on your Profile — is your guide and your helpdesk anywhere in the game. It can explain anything and walk you to the right place.',
    door: { to: '/profile', label: 'Meet my navitar' },
  },
  {
    emoji: '⚙️',
    title: 'Make it yours',
    body: 'Three quick bits of setup: pick your battle fighter in the Navidex, set your status so people know how to approach you, and flip the sound with the toggle in the top bar. Light or dark lives in Profile settings.',
  },
  {
    emoji: '🎉',
    title: 'You\u2019re in',
    body: 'That\u2019s the whole loop: walk, meet, battle, earn. These Instructions live in the menu any time — including a replay of this tour. Now go play.',
  },
];

const FirstRunTour: React.FC = () => {
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const timerRef = useRef<number | undefined>(undefined);

  useEffect(() => {
    const openTour = () => {
      setStep(0);
      setOpen(true);
    };
    const tryAutoOpen = () => {
      if (!tourAutoShowAllowed()) return;
      let welcomeSeen = false;
      try {
        welcomeSeen = !!localStorage.getItem(WELCOME_SEEN_KEY);
      } catch {
        welcomeSeen = true; // storage blocked: the welcome treats itself as seen too
      }
      if (!welcomeSeen) return; // the welcome still owns the screen
      timerRef.current = window.setTimeout(openTour, 650);
    };
    tryAutoOpen();
    window.addEventListener(WELCOME_DISMISSED_EVENT, tryAutoOpen);
    window.addEventListener(TOUR_REPLAY_EVENT, openTour);
    return () => {
      window.removeEventListener(WELCOME_DISMISSED_EVENT, tryAutoOpen);
      window.removeEventListener(TOUR_REPLAY_EVENT, openTour);
      if (timerRef.current !== undefined) window.clearTimeout(timerRef.current);
    };
  }, []);

  if (!open) return null;

  const current = STEPS[step];
  const isLast = step === STEPS.length - 1;

  const finish = () => {
    markTourSeen();
    setOpen(false);
  };

  const stopShowing = () => {
    markTourDismissed();
    setOpen(false);
  };

  const takeDoor = (to: string) => {
    finish();
    navigate(to);
  };

  return (
    <Dialog
      open={open}
      onClose={finish}
      fullWidth
      maxWidth="xs"
      data-testid="tour-dialog"
      aria-labelledby="tour-step-title"
    >
      <DialogContent sx={{ pt: 3 }}>
        <Box sx={{ textAlign: 'center', mb: 1.5 }}>
          <Typography variant="h2" component="div" aria-hidden data-testid="tour-step-emoji">
            {current.emoji}
          </Typography>
        </Box>
        <Typography
          id="tour-step-title"
          variant="h6"
          align="center"
          gutterBottom
          data-testid="tour-step-title"
        >
          {current.title}
        </Typography>
        <Typography variant="body1" align="center" data-testid="tour-step-body">
          {current.body}
        </Typography>
        {current.door && (
          <Box sx={{ textAlign: 'center', mt: 2 }}>
            <Button
              variant="outlined"
              onClick={() => takeDoor(current.door!.to)}
              data-testid="tour-door"
            >
              {current.door.label} →
            </Button>
          </Box>
        )}
        <Box sx={{ mt: 3 }}>
          <LinearProgress
            variant="determinate"
            value={((step + 1) / STEPS.length) * 100}
            sx={{ borderRadius: 2, height: 8 }}
          />
          <Typography
            variant="caption"
            color="text.secondary"
            sx={{ display: 'block', textAlign: 'center', mt: 0.75 }}
            data-testid="tour-progress"
          >
            Step {step + 1} of {STEPS.length}
          </Typography>
        </Box>
      </DialogContent>
      <Box sx={{ px: 3, pb: 1, display: 'flex', justifyContent: 'space-between', gap: 1 }}>
        <Button
          variant="outlined"
          disabled={step === 0}
          onClick={() => setStep(s => Math.max(0, s - 1))}
          data-testid="tour-back"
        >
          ← Back
        </Button>
        <Button
          variant="contained"
          onClick={() => (isLast ? finish() : setStep(s => s + 1))}
          data-testid="tour-next"
        >
          {isLast ? 'Start playing 🎉' : 'Next →'}
        </Button>
      </Box>
      <Box
        sx={{
          px: 3,
          pb: 2,
          display: 'flex',
          justifyContent: 'space-between',
          gap: 1,
          flexWrap: 'wrap',
        }}
      >
        <Button size="small" onClick={finish} data-testid="tour-skip">
          Skip the tour
        </Button>
        <Button
          size="small"
          color="inherit"
          onClick={stopShowing}
          data-testid="tour-stop"
          sx={{ color: 'text.secondary' }}
        >
          Stop showing me this
        </Button>
      </Box>
    </Dialog>
  );
};

export default FirstRunTour;
