import React, { useLayoutEffect, useMemo, useRef, useState } from 'react';
import { Box } from '@mui/material';
import { elementColor } from '../utils/navitarArt';
import { getCollectibleCard } from '../utils/collectibleCards';
import { cardDataFor } from '../utils/cardData';
import { NavitarDesign } from './NavitarDesign';

// The SUMMON visual (Round 24, Eddie 2026-11-18): while a fighter's
// 3D model is still travelling (the GLBs run 20–28 MB), the slot
// shows the fighter's card instead of a spinner over a portrait;
// when the model is ready the caller swaps it in — the two never
// flap back and forth, the swap happens once, on load.
//
// Round 30 (Eddie, 2026-11-18 ~10:35 PT): the loading screen IS
// the card — not the bare collectible artwork, but the fighter's
// FULL player card in its trading-card dress (header band with
// name / HP / element, framed art window, stat rows, lore flavor
// line, power tracker), resolved from the same data the Navidex
// renders (utils/cardData) so there is ONE card design
// everywhere: grid, Stage veil, ModelViewer in cards / Profile /
// AR. The dressed card is rendered at its natural design width
// and CONTAIN-scaled to its container — never cropped, never
// overflowing; if a fighter somehow has collectible art but no
// card data anywhere, the bare artwork treatment below remains
// as the fallback, and a fighter with no collectible card at
// all renders nothing here (the caller keeps its previous
// loading treatment) — this component never invents art or data.
// Realm Elements rule (same direction): while the card stands
// it presents CLEAN — no background graphics behind it; the
// Realm Elements belong to the loaded 3D character.

// The card's natural design width — the Navidex grid's own card
// width on desktop; the dressed card is composed at this width
// and scaled from it.
const DESIGN_W = 340;

export const SummonCard: React.FC<{
  name: string;
  element: string;
  style?: React.CSSProperties;
}> = ({ name, element, style }) => {
  const src = getCollectibleCard(name);
  const outerRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const [bounds, setBounds] = useState({ w: 0, h: 0 });
  const [cardH, setCardH] = useState(0);
  // Memoized by fighter: a fresh props object per render would
  // re-run the measuring effect below on every render and loop
  // (React #185) — the card's data changes only with its name.
  const data = useMemo(() => (src ? cardDataFor(name) : null), [src, name]);

  // Contain-fit measurement: the container's box and the card's
  // natural (unscaled) height, both via ResizeObserver — the
  // card is then scaled by the smaller of the two fits, so the
  // whole card is always visible, exactly once, at any size.
  // The setters bail out on unchanged values so a ResizeObserver
  // notification can never feed a render loop.
  useLayoutEffect(() => {
    if (!data) return;
    const outer = outerRef.current;
    const card = cardRef.current;
    if (!outer || !card) return;
    const read = () => {
      const r = outer.getBoundingClientRect();
      const w = r.width;
      const h = r.height;
      const ch = card.offsetHeight;
      setBounds(prev => (prev.w === w && prev.h === h ? prev : { w, h }));
      setCardH(prev => (prev === ch ? prev : ch));
    };
    read();
    const ro = new ResizeObserver(read);
    ro.observe(outer);
    ro.observe(card);
    return () => ro.disconnect();
  }, [data]);

  if (!src) return null;
  const color = elementColor(element);

  if (!data) {
    // Bare-art fallback (the Round 24 treatment): collectible
    // art exists but no card data resolves for this name.
    return (
      <Box
        data-summon-card={name}
        sx={{
          position: 'relative',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          overflow: 'hidden',
          background: `radial-gradient(circle at 50% 32%, ${color}55, var(--glacer-art-tile-end, #10151c) 78%)`,
          ...style,
        }}
      >
        <Box
          aria-hidden
          sx={{
            position: 'absolute',
            width: '62%',
            aspectRatio: '1',
            borderRadius: '50%',
            background: `radial-gradient(circle, ${color}66, transparent 70%)`,
            animation: 'glacer-summon-breathe 2.6s ease-in-out infinite',
            '@keyframes glacer-summon-breathe': {
              '0%, 100%': { transform: 'scale(0.92)', opacity: 0.55 },
              '50%': { transform: 'scale(1.08)', opacity: 0.95 },
            },
          }}
        />
        <img
          src={src}
          alt={`${name} collectible card`}
          style={{
            position: 'relative',
            maxWidth: '100%',
            maxHeight: '100%',
            width: 'auto',
            height: '100%',
            objectFit: 'contain',
            display: 'block',
            borderRadius: 10,
            boxShadow: `0 10px 34px rgba(0,0,0,0.55), 0 0 22px ${color}55`,
          }}
        />
      </Box>
    );
  }

  const scale =
    bounds.w > 0 && bounds.h > 0 && cardH > 0 ? Math.min(bounds.w / DESIGN_W, bounds.h / cardH) : 0;
  return (
    <Box
      ref={outerRef}
      data-summon-card={name}
      sx={{
        position: 'relative',
        overflow: 'hidden',
        background: `radial-gradient(circle at 50% 32%, ${color}55, var(--glacer-art-tile-end, #10151c) 78%)`,
        ...style,
      }}
    >
      {/* Realm Elements rule (Eddie, Round 30): while the card
          stands, it presents CLEAN — no breathing glow or other
          background graphics behind it; the Realm Elements
          return with the loaded 3D character. The backdrop is
          the slot's quiet static tint only. */}
      <Box
        sx={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          width: DESIGN_W,
          transform: `translate(-50%, -50%) scale(${scale})`,
          transformOrigin: 'center',
          opacity: scale > 0 ? 1 : 0,
        }}
      >
        <div ref={cardRef}>
          <NavitarDesign {...data} collectibleArt uniformFrame />
        </div>
      </Box>
    </Box>
  );
};

export default SummonCard;
