// Bottom tab bar (Eddie, 2026-11-16) — the Modern View prototype's
// phone navigation, brought into the real app shell: on phone
// widths the primary destinations live in a fixed glass tab bar at
// the bottom of the screen, thumb-reachable, with the active tab
// lit in the accent.
//
// NETWORKING IS THE CENTERPIECE (Eddie, 2026-11-16 ~11:09 PT:
// "we just need to have a higher tool for networking because
// that's the main part of the thing, and a more convenient button
// for networking"). GLACER's mission is making social media
// social again — stranger → met → battled → friend — so the
// middle slot is a RAISED, accent-filled circular Networking
// button that sits above the bar, the classic main-action
// treatment. Bar set: Home · Map · NETWORKING (raised center) ·
// Navidex · Stroll · Battle. Stroll joined in Round 14 (Eddie,
// 2026-11-17: "there should be a clear menu stroll button, along
// with the other buttons") — it had been reachable only through
// Home links and the top-bar menu. "More" (/features, the All
// Features hub) stays out of the bar — it remains reachable from
// the top bar's menu (which lists all destinations, Networking
// included) and from links on Home; no destination is
// unreachable. Six slots at phone widths: each keeps its icon +
// label (the center label steps down a size so "Networking"
// never crowds its slot).
//
// Desktop keeps the existing top nav exactly as it was — this bar
// renders below the md breakpoint only. The top bar keeps the logo,
// the ART⇄3D toggle, the sound mute and Log in / Sign up at every
// width.
//
// Collisions: the bar is zIndex 1150 — above page content, below
// the fight screen's full-viewport overlay (1200), the result
// dialog (1300) and the notification pills (1290/1300), so a duel
// covers it completely and battle buttons never share space with
// it. Page clearance lives in modern.css (.app bottom padding on
// phone widths); Stroll's AR controls and the map's panels sit in
// normal page flow and scroll clear of the bar. The raised center
// button overflows the bar's top edge by ~14px — it is still
// inside the bar's fixed box (the bar has no overflow hidden),
// and page bottom padding already clears the whole bar.
import React from 'react';
import { Box, Typography } from '@mui/material';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import { useThemeMode } from '../contexts/ThemeModeContext';
import HomeRoundedIcon from '@mui/icons-material/HomeRounded';
import MapRoundedIcon from '@mui/icons-material/MapRounded';
import GridViewRoundedIcon from '@mui/icons-material/GridViewRounded';
import DirectionsWalkRoundedIcon from '@mui/icons-material/DirectionsWalkRounded';
import SportsMartialArtsRoundedIcon from '@mui/icons-material/SportsMartialArtsRounded';
import PeopleRoundedIcon from '@mui/icons-material/PeopleRounded';

interface TabDef {
  to: string;
  label: string;
  icon: React.ReactNode;
  matches: (pathname: string) => boolean;
}

const SIDE_TABS_LEFT: TabDef[] = [
  { to: '/', label: 'Home', icon: <HomeRoundedIcon />, matches: p => p === '/' },
  {
    to: '/map',
    label: 'Map',
    icon: <MapRoundedIcon />,
    matches: p => p === '/map',
  },
];

const SIDE_TABS_RIGHT: TabDef[] = [
  {
    to: '/collection',
    label: 'Navidex',
    icon: <GridViewRoundedIcon />,
    matches: p => p === '/collection',
  },
  {
    // Round 14: Stroll gets its own clear tab (Eddie: "a clear
    // menu stroll button, along with the other buttons"). It sits
    // between Navidex and Battle — pick your fighter, walk with
    // it, fight — and /stroll's own path lights it (Stroll's
    // internal Scene / Map / 3D Map views never change the path).
    to: '/stroll',
    label: 'Stroll',
    icon: <DirectionsWalkRoundedIcon />,
    matches: p => p === '/stroll',
  },
  {
    to: '/battle',
    label: 'Battle',
    icon: <SportsMartialArtsRoundedIcon />,
    matches: p => p === '/battle',
  },
];

const NETWORKING_TAB: TabDef = {
  to: '/networking',
  label: 'Networking',
  icon: <PeopleRoundedIcon />,
  matches: p => p === '/networking',
};

const sideTabSx = (active: boolean, dark: boolean) => ({
  flex: 1,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  gap: '3px',
  minHeight: 56,
  py: 0.75,
  borderRadius: '16px',
  textDecoration: 'none',
  // Theme-aware (Round 11): the accent deepens and the idle label
  // darkens on the white bar so both read at a glance.
  color: active ? (dark ? '#12a5c7' : '#0b7d9b') : dark ? '#9dbec9' : '#4d6b78',
  bgcolor: active ? 'rgba(18, 165, 199, 0.16)' : 'transparent',
  transition:
    'color 0.3s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.35s cubic-bezier(0.22, 1.24, 0.36, 1)',
  '&:active': { transform: 'scale(0.96)' },
  '& .MuiSvgIcon-root': { fontSize: 23 },
});

const tabLabelSx = {
  fontSize: '0.72rem',
  fontWeight: 800,
  letterSpacing: '0.04em',
  lineHeight: 1,
} as const;

const BottomTabBar: React.FC = () => {
  const { pathname } = useLocation();
  const { mode } = useThemeMode();
  const dark = mode === 'dark';
  const networkingActive = NETWORKING_TAB.matches(pathname);

  // Re-tapping the tab for the page you're already on scrolls that
  // page back to the top (Round 10 add-on): the route doesn't
  // change, so the router-level ScrollToTop never fires — this is
  // its same-page companion. Instant, exactly like the navigation
  // reset: every trip to the top in this app behaves the same, and
  // an animated scroll can be starved or cancelled under load —
  // the player asked for the top, not a maybe.
  const retapScrollTop = (active: boolean) => () => {
    if (active) window.scrollTo(0, 0);
  };

  const renderSideTab = (tab: TabDef) => {
    const active = tab.matches(pathname);
    return (
      <Box
        key={tab.to}
        component={RouterLink}
        to={tab.to}
        onClick={retapScrollTop(active)}
        aria-current={active ? 'page' : undefined}
        data-testid={`tab-${tab.label.toLowerCase()}`}
        sx={sideTabSx(active, dark)}
      >
        {tab.icon}
        <Typography variant="caption" sx={tabLabelSx}>
          {tab.label}
        </Typography>
      </Box>
    );
  };

  return (
    <Box
      component="nav"
      aria-label="Primary"
      data-testid="bottom-tab-bar"
      sx={{
        display: { xs: 'flex', md: 'none' },
        position: 'fixed',
        left: 0,
        right: 0,
        bottom: 0,
        zIndex: 1150,
        bgcolor: dark ? 'rgba(7, 24, 34, 0.88)' : 'rgba(255, 255, 255, 0.88)',
        backdropFilter: 'blur(18px)',
        WebkitBackdropFilter: 'blur(18px)',
        borderTop: dark
          ? '1px solid rgba(120, 200, 225, 0.16)'
          : '1px solid rgba(11, 125, 155, 0.18)',
        px: 1,
        pt: 0.75,
        pb: 'calc(8px + env(safe-area-inset-bottom))',
      }}
    >
      <Box
        sx={{
          display: 'flex',
          width: '100%',
          maxWidth: 560,
          mx: 'auto',
          alignItems: 'flex-end',
        }}
      >
        {SIDE_TABS_LEFT.map(renderSideTab)}
        {/* The raised center: Networking — the main part of the
            thing gets the main button. A filled accent circle
            lifted above the bar, label under it; active state
            brightens the fill and adds the gold ring so it reads
            as "you are here" without losing its prominence. */}
        <Box
          component={RouterLink}
          to={NETWORKING_TAB.to}
          onClick={retapScrollTop(networkingActive)}
          aria-current={networkingActive ? 'page' : undefined}
          data-testid="tab-networking"
          sx={{
            flex: 1,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'flex-end',
            gap: '3px',
            minHeight: 56,
            py: 0.75,
            textDecoration: 'none',
            color: networkingActive ? (dark ? '#ffd54f' : '#9a6b00') : dark ? '#eaf6fa' : '#0d2b38',
            transition: 'color 0.3s cubic-bezier(0.16, 1, 0.3, 1)',
            '&:active': { transform: 'scale(0.96)' },
          }}
        >
          <Box
            sx={{
              width: 54,
              height: 54,
              mt: '-26px',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              background: networkingActive
                ? 'linear-gradient(150deg, #17b6da, #0b7d9b)'
                : 'linear-gradient(150deg, #12a5c7, #0a6d8a)',
              border: networkingActive
                ? '2px solid #ffd54f'
                : dark
                  ? '2px solid rgba(234, 246, 250, 0.35)'
                  : '2px solid rgba(255, 255, 255, 0.9)',
              boxShadow: networkingActive
                ? '0 6px 22px rgba(18, 165, 199, 0.65), 0 0 0 4px rgba(255, 213, 79, 0.25)'
                : '0 6px 18px rgba(18, 165, 199, 0.5)',
              color: '#eaf6fa',
              transition:
                'box-shadow 0.35s cubic-bezier(0.22, 1.24, 0.36, 1), background 0.3s ease',
              '& .MuiSvgIcon-root': { fontSize: 28 },
            }}
          >
            {NETWORKING_TAB.icon}
          </Box>
          <Typography
            variant="caption"
            sx={{ ...tabLabelSx, fontWeight: 900, fontSize: '0.68rem', letterSpacing: '0.02em' }}
          >
            {NETWORKING_TAB.label}
          </Typography>
        </Box>
        {SIDE_TABS_RIGHT.map(renderSideTab)}
      </Box>
    </Box>
  );
};

export default BottomTabBar;
